  for i=1,M.MAX_LINKS do local id=p.simultaneous_play_targets[i];f[#f+1]=id and integer(assert(pads[id],"unknown simultaneous target").logical_index,"target",1,128)or 0 end;f[#f+1]=#p.mute_targets;for i=1,M.MAX_LINKS do local id=p.mute_targets[i];f[#f+1]=id and integer(assert(pads[id],"unknown mute target").logical_index,"target",1,128)or 0 end;local controls=p.default_controls or{};local pan=controls.pan;if pan==nil then pan=.5 end;if type(pan)~="number"or pan<0 or pan>1 then die("Pad["..pi.."].default_controls.pan","normalized number out of range [0,1]")end;f[#f+1]=math.floor((pan*2-1)*100+(pan>=.5 and .5 or-.5));f[#f+1]=p.sample~=false and p.sample~=nil and 1 or 0;f[#f+1]=controls.legato_enabled==false and 0 or 1;add(w,M.TAG.PAD,f)end
 local groups=rack.round_robin_groups or{};if #groups>M.MAX_GROUPS then die("Rack.round_robin_groups","capacity exceeded")end
