  if #g.member_pad_ids<2 or #g.member_pad_ids>M.MAX_GROUP_MEMBERS then die("RoundRobinGroup["..gi.."]","member capacity exceeded")end
  local mode=M.RR_MODE[g.mode];local reset=M.RR_RESET[g.reset_policy];if mode==nil or reset==nil then die("RoundRobinGroup["..gi.."]","unsupported mode/reset")end
  local master=assert(pads[g.master_pad_id],"unknown round robin master");local f={integer(master.logical_index,"master",1,128),mode,ppm(g.probability,"probability"),reset,integer(g.seed,"seed",0,2147483647),g.advance_on_skip and 1 or 0,g.advance_each_repeat and 1 or 0,#g.member_pad_ids}
  for i=1,M.MAX_GROUP_MEMBERS do local id=g.member_pad_ids[i];f[#f+1]=id and integer(assert(pads[id],"unknown round robin member").logical_index,"member",1,128)or 0 end;add(w,M.TAG.GROUP,f)
