 for pi,p in ipairs(rack.patterns or{})do tick();add(w,M.TAG.PATTERN,{hid(p.id,"Pattern.id"),integer(p.seed,"Pattern.seed",0,2147483647),#p.variations});for vi,v in ipairs(p.variations)do tick();vc=vc+1;if vc>M.MAX_VARIATIONS then die("Variation","capacity exceeded")end;local q,qn,qd=quant(v.switch_quantization,"Variation.switch_quantization");add(w,M.TAG.VARIATION,{hid(v.id,"Variation.id"),pi,q,qn,qd,#v.lanes});if v.groove then local g=v.groove;local count=integer(g.cycle_steps,"Variation.groove.cycle_steps",1,M.MAX_GROOVE_STEPS);if type(g.timing_offsets)~="table"or#g.timing_offsets~=count then die("Variation.groove.timing_offsets","cycle length mismatch")end;local fields={vc,integer(g.grid_num,"Variation.groove.grid_num",1,2147483647),integer(g.grid_den,"Variation.groove.grid_den",1,2147483647),count,math.floor(math.max(0,math.min(100,tonumber(v.groove_strength)or tonumber(v.swing)or 0))*1000+0.5)};for gi=1,count do fields[#fields+1]=integer(g.timing_offsets[gi],"Variation.groove.timing_offsets["..gi.."]",-960,960)end;add(w,M.TAG.GROOVE,fields)end;local lane_refs={};for lno,l in ipairs(v.lanes)do if lane_refs[l.id]then die("Lane["..lno.."].id","duplicate lane ID in variation")end;lane_refs[l.id]=hid(l.id,"Lane.id")end
    for _,l in ipairs(v.lanes)do tick();lc=lc+1;if lc>M.MAX_LANES then die("Lane","capacity exceeded")end;local pad=assert(pads[l.pad_id],"unknown lane pad");add(w,M.TAG.LANE,{lane_refs[l.id],vc,integer(pad.logical_index,"Lane.pad",1,128),integer(l.step_count,"Lane.step_count",1,4096),integer(l.division_num,"Lane.division_num",1,2147483647),integer(l.division_den,"Lane.division_den",1,2147483647),integer(l.phase,"Lane.phase",0,l.step_count-1),math.floor(l.swing*1000+0.5),math.floor(math.max(0,math.min(200,tonumber(l.velocity_sensitivity) or 100))*100+0.5),l.groove_enabled==false and 0 or 1})
     for _,s in ipairs(l.steps)do tick();sc=sc+1;if sc>M.MAX_STEPS then die("Step","capacity exceeded")end;locks=locks+#s.parameter_locks;if locks>M.MAX_LOCKS then die("ParameterLock","capacity exceeded")end;local rn,rd=rat(s.repeat_spacing,"Step.repeat_spacing");local ck,ca,cb=condition(s.condition,"Step.condition",lane_refs);add(w,M.TAG.STEP,{s.cut and 2 or(s.enabled and(s.runtime_one_shot and 3 or 1)or 0),integer(s.velocity,"Step.velocity",1,127),integer(s.pitch_semitones,"Step.pitch_semitones",-96,96),integer(s.pitch_cents,"Step.pitch_cents",-100,100),s.pan_lock==false and 1001 or integer(s.pan_lock,"Step.pan_lock",-100,100),integer(s.repeat_count,"Step.repeat_count",1,64),rn,rd,ppm(s.probability,"Step.probability"),integer(s.timing_offset,"Step.timing_offset",-960,960),ppm(s.gate,"Step.gate"),ck,ca,cb,s.slide and 1 or 0,#s.parameter_locks});for _,k in ipairs(s.parameter_locks)do tick();local kind,val=type(k.value)=="boolean"and 1 or type(k.value)=="number"and 2 or nil;if not kind then die("ParameterLock.value","runtime supports boolean or numeric values")end;val=kind==1 and(k.value and 1 or 0)or k.value;add(w,M.TAG.LOCK,{hid(k.parameter_id,"ParameterLock.parameter_id"),kind,val,hid(k.interpolation,"ParameterLock.interpolation")})end end
